    }
  ],
  "hypotheses": [
    {
      "service": "invoice-agent",
      "kind": "bad_input",
      "mechanism": "Supplier 'Red Sea Parts' started sending invoices in a new layout around t=505 that invoice-agent's extraction logic cannot parse, causing worker to exhaust retry budgets on every affected order.",
      "supporting": ["E1", "E3", "E4", "E13"],
      "refuting": ["E14"],
      "explains": ["I6_retry_budget"],
      "repair_plan": []
    }
  ],
  "summary": "All 5 retry-budget violations are orders from supplier 'Red Sea Parts' whose invoice layout changed around t=505, causing invoice-agent extraction to fail repeatedly; sync-job v2.0 is not implicated as ledger data looks healthy and sync-job does not write to orders."
}
